/bin/bash -lc "python - <<'PY'
import json
a=json.load(open('canonical-input.json'))
for k in a:
 if k not in ('originals','candidates','contextGoals'): print(k,json.dumps(a[k],ensure_ascii=False,indent=2))
for k in ('originals','candidates','contextGoals'):
 print(k,a[k][0].keys())
 for v in a[k]: print(str([(x,v[x]) for x in v if x in ('goalId','id','shortKey','title','requires')])[:500])
PY"

