import json,collections
a=json.load(open('canonical-input.json')); gs={c['goal']['id']:c['goal'] for c in a['contextGoals']}
def sweep(start):
 closed=set(); pending=list(start)
 while pending:
  n=pending.pop()
  if n in closed: continue
  closed.add(n); pending+=gs[n]['requires']
 return closed
allgo=set()
for x in a['candidates']:
 reach=sweep(x['requires']);allgo|=reach
 print(x['id'][:8],len(reach),[gs[n]['title'] for n in sorted(reach) if 'canonical' in gs[n].get('tags',[]) and 'physics' in gs[n].get('dimensionTags',{}).get('framework','')])
print('Other context goals:',[gs[n]['title'] for n in set(gs)-allgo if n not in a['scopeGoalIds']])
for n in set(gs)-allgo:
 if n not in a['scopeGoalIds']:
  g=gs[n]
  print(n,g['description'],g.get('descriptionEn'),g['requires'],g.get('examData',{}).get('coveredGoalIds'))
PY"

